import {
  ArrowLeft,
  Calendar,
  CheckCircle,
  Clock,
  Ear,
  Heart,
  MapPin,
  MessageCircle,
  Scale,
  Shield,
  Sparkles,
  Users,
} from 'lucide-react'
import Link from 'next/link'

const courses = [
  {
    title: 'Écoute active et empathie',
    icon: <Ear className="w-6 h-6 text-emerald-600" />,
    description: 'Accueillir l\'autre avec attention, respect et présence authentique',
  },
  {
    title: 'Communication non-violente',
    icon: <MessageCircle className="w-6 h-6 text-teal-600" />,
    description: 'Exprimer les besoins et gérer les conflits avec bienveillance',
  },
  {
    title: 'Gestion des émotions et du stress',
    icon: <Heart className="w-6 h-6 text-rose-600" />,
    description: 'Comprendre et accompagner les réactions émotionnelles en situation d\'aide',
  },
  {
    title: 'Relations de confiance',
    icon: <Users className="w-6 h-6 text-blue-600" />,
    description: 'Établir un cadre relationnel sûr et durable avec la personne aidée',
  },
  {
    title: 'Conseil et orientation spirituelle',
    icon: <Sparkles className="w-6 h-6 text-amber-600" />,
    description: 'Allier discernement biblique et accompagnement pastoral',
  },
  {
    title: 'Éthique et limites professionnelles',
    icon: <Shield className="w-6 h-6 text-violet-600" />,
    description: 'Intervenir avec intégrité, confidentialité et clarté des rôles',
  },
]

export default function RelationAideEcoleContent() {
  return (
    <main className="bg-gradient-to-b from-background to-emerald-50/30">
      <div className="max-w-6xl mx-auto px-3 sm:px-4 lg:px-6 py-3 sm:py-4 pb-6">
        <Link
          href="/ecoles"
          className="inline-flex items-center gap-1.5 text-xs sm:text-sm text-primary hover:text-primary/80 transition mb-3"
        >
          <ArrowLeft className="w-3.5 h-3.5 sm:w-4 sm:h-4 shrink-0" />
          Retour aux écoles
        </Link>

        <div className="text-center mb-4">
          <div className="space-y-2">
            <div className="flex flex-wrap items-center justify-center gap-1.5 sm:gap-2">
              <div className="text-xl sm:text-2xl leading-none" aria-hidden>
                🤝
              </div>
              <div className="flex flex-wrap justify-center gap-1.5">
                <span className="inline-flex items-center gap-1 bg-green-100 text-green-800 text-[10px] sm:text-xs font-medium px-2 py-0.5 rounded-full">
                  <CheckCircle className="w-3 h-3 shrink-0" />
                  Formation disponible
                </span>
                <span className="inline-flex items-center gap-1 bg-emerald-100 text-emerald-800 text-[10px] sm:text-xs font-medium px-2 py-0.5 rounded-full">
                  <Clock className="w-3 h-3 shrink-0" />
                  12 semaines
                </span>
              </div>
            </div>
            <h1 className="text-xl sm:text-2xl md:text-3xl font-bold text-primary leading-tight">
              École Relation d&apos;Aide
            </h1>
            <p className="text-xs sm:text-sm text-foreground/80 leading-relaxed max-w-3xl mx-auto">
              Formez-vous à accompagner, soutenir et conseiller avec empathie et professionnalisme, en combinant
              principes bibliques et compétences relationnelles concrètes.
            </p>
            <Link
              href="/inscription"
              className="inline-flex items-center justify-center px-4 py-2 text-xs sm:text-sm bg-green-600 text-white rounded-md font-semibold hover:bg-green-700 transition"
            >
              S&apos;inscrire maintenant
            </Link>
          </div>
        </div>

        <div className="bg-white rounded-lg shadow-sm p-3 sm:p-4 border border-emerald-100 mb-4">
          <h2 className="text-sm sm:text-base font-bold text-primary mb-2 flex items-center gap-1.5">
            <CheckCircle className="w-4 h-4 text-green-500 shrink-0" />
            À propos de la formation
          </h2>

          <div className="grid md:grid-cols-2 gap-3">
            <div className="space-y-3">
              <p className="text-xs sm:text-sm text-foreground/70 leading-relaxed">
                L&apos;École Relation d&apos;Aide prépare des accompagnants qualifiés pour soutenir les personnes en
                difficulté. Vous développerez les compétences essentielles d&apos;écoute, d&apos;empathie et de
                conseil pour faire une différence positive dans la vie des autres.
              </p>

              <div>
                <h3 className="text-xs sm:text-sm font-semibold text-foreground/90 mb-1">
                  Objectifs de la formation
                </h3>
                <div className="space-y-1 text-xs sm:text-sm text-foreground/70">
                  <p className="flex items-start gap-1.5">
                    <CheckCircle className="w-3.5 h-3.5 text-green-500 mt-0.5 flex-shrink-0" />
                    <span>Pratiquer une écoute active et une présence bienveillante</span>
                  </p>
                  <p className="flex items-start gap-1.5">
                    <CheckCircle className="w-3.5 h-3.5 text-green-500 mt-0.5 flex-shrink-0" />
                    <span>Accompagner avec discernement dans diverses situations de vie</span>
                  </p>
                  <p className="flex items-start gap-1.5">
                    <CheckCircle className="w-3.5 h-3.5 text-green-500 mt-0.5 flex-shrink-0" />
                    <span>Respecter l&apos;éthique et les limites de la relation d&apos;aide</span>
                  </p>
                </div>
              </div>

              <div className="text-[0.65rem] sm:text-xs text-emerald-900 bg-emerald-50 p-2 sm:p-2.5 rounded-md border border-emerald-100 leading-relaxed flex items-start gap-2">
                <Scale className="w-4 h-4 shrink-0 mt-0.5 text-emerald-600" />
                <span>
                  Formation holistique : enseignements bibliques, mises en situation et jeux de rôle pour une
                  pratique concrète et responsable.
                </span>
              </div>
            </div>

            <div className="bg-emerald-50 p-2.5 sm:p-3 rounded-md border border-emerald-100">
              <h3 className="text-xs sm:text-sm font-semibold text-foreground/90 mb-2">Informations pratiques</h3>
              <div className="space-y-2">
                <div className="flex items-start gap-2">
                  <div className="bg-emerald-100 p-1 rounded text-emerald-600 shrink-0">
                    <Clock className="w-3.5 h-3.5" />
                  </div>
                  <div className="min-w-0">
                    <p className="text-xs sm:text-sm font-medium">Durée</p>
                    <p className="text-foreground/70 text-[0.65rem] sm:text-xs">12 semaines</p>
                  </div>
                </div>
                <div className="flex items-start gap-2">
                  <div className="bg-emerald-100 p-1 rounded text-emerald-600 shrink-0">
                    <Calendar className="w-3.5 h-3.5" />
                  </div>
                  <div className="min-w-0">
                    <p className="text-xs sm:text-sm font-medium">Fréquence</p>
                    <p className="text-foreground/70 text-[0.65rem] sm:text-xs">2 séances par semaine (2 h 30 chacune)</p>
                  </div>
                </div>
                <div className="flex items-start gap-2">
                  <div className="bg-emerald-100 p-1 rounded text-emerald-600 shrink-0">
                    <Users className="w-3.5 h-3.5" />
                  </div>
                  <div className="min-w-0">
                    <p className="text-xs sm:text-sm font-medium">Effectif</p>
                    <p className="text-foreground/70 text-[0.65rem] sm:text-xs">Groupes de 12 à 20 personnes</p>
                  </div>
                </div>
                <div className="flex items-start gap-2">
                  <div className="bg-emerald-100 p-1 rounded text-emerald-600 shrink-0">
                    <MapPin className="w-3.5 h-3.5" />
                  </div>
                  <div className="min-w-0">
                    <p className="text-xs sm:text-sm font-medium">Format &amp; lieu</p>
                    <p className="text-foreground/70 text-[0.65rem] sm:text-xs">En présentiel à Aného, avec mises en pratique</p>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>

        <div className="mb-4">
          <h2 className="text-sm sm:text-base font-bold text-primary mb-2">Modules de formation</h2>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-2 sm:gap-2.5">
            {courses.map((course) => (
              <div
                key={course.title}
                className="border border-emerald-500/20 rounded-md p-2.5 sm:p-3 bg-white shadow-sm hover:shadow transition-shadow"
              >
                <div className="flex items-start gap-2 mb-1">
                  <div className="p-1 bg-emerald-500/10 rounded shrink-0 [&_svg]:w-4 [&_svg]:h-4">
                    {course.icon}
                  </div>
                  <h3 className="font-bold text-primary text-xs sm:text-sm leading-snug">{course.title}</h3>
                </div>
                <p className="text-foreground/70 text-[0.65rem] sm:text-xs leading-relaxed">{course.description}</p>
              </div>
            ))}
          </div>
          <p className="mt-2 text-[0.65rem] sm:text-xs text-muted-foreground italic">
            Apprentissage expérientiel : études de cas, jeux de rôle et retours en groupe.
          </p>
        </div>

        <div className="flex flex-col sm:flex-row gap-2 pt-1">
          <Link
            href="/inscription"
            className="px-4 py-2 text-xs sm:text-sm bg-green-600 text-white rounded-md font-semibold hover:bg-green-700 transition text-center"
          >
            S&apos;inscrire maintenant
          </Link>
          <Link
            href="/contact"
            className="px-4 py-2 text-xs sm:text-sm border border-primary text-primary rounded-md font-semibold hover:bg-primary/5 transition text-center"
          >
            Nous contacter
          </Link>
        </div>
      </div>
    </main>
  )
}
